import React from "react";
import PropTypes from "prop-types";

import applyReducers from "@traveloka/soya-components/lib/legacy/applyReducers";
import {
  commonRulesMapDisToProps,
  commonRulesReducers,
  commonRulesSelector,
} from "./CommonRuleRedux";
import { compose } from "redux";
import { connect } from "react-redux";
import { Button, Label } from "@traveloka/soya-components";
import DropdownInput from "./DropdownInput";

import * as style from "./CommonRule.styles";

class ConditionModal extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      root: props.existingValue
        ? props.existingValue
        : this.getDefaultOperator(props.ruleStructures),
    };
  }

  getDefaultOperator = (ruleStructures) => {
    const expressionStructure = JSON.parse(ruleStructures.expressionStructure);
    for (const i in expressionStructure) {
      if (expressionStructure[i].type === "operator") {
        return i;
      }
    }
    return null;
  };

  getDropdownItems = () => {
    const options = [];
    const { ruleStructures } = this.props;
    const expressionStructure = JSON.parse(ruleStructures.expressionStructure);
    for (const i in expressionStructure) {
      if (expressionStructure[i].type === "operator") {
        options.push({ label: this.getOperatorLabel(i), value: i });
      }
    }
    return options;
  };

  getOperatorLabel = (operatorId) => {
    const { ruleStructures } = this.props;
    const formatterStructure = JSON.parse(ruleStructures.formatterStructure);
    return formatterStructure[operatorId].label;
  };

  render() {
    const { root } = this.state;
    const rootItems = this.getDropdownItems();
    return (
      <div>
        <div>
          <Label>{"Condition"}</Label>
          <DropdownInput
            value={root}
            name="root"
            onChange={this.handleSelectChange}
            items={rootItems}
          />
        </div>
        <div className={style.modalFooter}>
          <Button onClick={this.handleCancel} color="link">
            {"Close"}
          </Button>
          <Button onClick={this.handleSave} color="blue">
            {"OK"}
          </Button>
        </div>
      </div>
    );
  }

  handleSelectChange = (name, value) => {
    const stateObj = {};
    stateObj[name] = value;
    this.setState(stateObj);
  };

  handleCancel = () => {
    const { onCancel } = this.props;
    onCancel();
  };

  handleSave = () => {
    const { onSave } = this.props;
    const { root } = this.state;
    onSave({
      root,
    });
  };
}

ConditionModal.propTypes = {
  existingValue: PropTypes.string,
  onCancel: PropTypes.func.isRequired,
  onSave: PropTypes.func.isRequired,
  ruleStructures: PropTypes.string.isRequired,
};

const mapStateToProps = (state, ownProps) => ({
  ruleStructures: commonRulesSelector.getRuleStructures(state),
});

export default compose(
  applyReducers(commonRulesReducers),
  connect(mapStateToProps, commonRulesMapDisToProps)
)(ConditionModal);
